// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/actions", wrapper.GetWorkerActions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/execute/{workerKey}", wrapper.ExecuteHttpTriggeredWorker)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/execution_history", wrapper.GetWorkerExecutionHistory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/rerun/{workerKey}", wrapper.RerunWorker)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/scaffold/tsconfig", wrapper.GetWorkerScaffoldTsConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/system/liveness", wrapper.CheckWorkersLiveness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/system/readiness", wrapper.CheckWorkersReadiness)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/test", wrapper.ExecuteWorkerTestGeneric)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/test/{workerKey}", wrapper.ExecuteWorkerTest)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workers", wrapper.GetWorkers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workers", wrapper.CreateWorker)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/workers", wrapper.UpdateWorker)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/workers/{workerKey}", wrapper.DeleteWorker)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workers/{workerKey}", wrapper.GetWorker)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/actions", wrapper.GetWorkerActionsMetadata)
	})

	return r
}

